#!/usr/bin/env python3
"""Generate the English scientific PDF from actual recorded paceval results.
Requires reportlab, matplotlib, numpy, Pillow. The runtime library is not bundled.
"""
from pathlib import Path
import json, csv, math
import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.platypus import BaseDocTemplate, PageTemplate, Frame, Paragraph, Spacer, Image, PageBreak, Table, TableStyle, HRFlowable, KeepTogether
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.styles import ParagraphStyle
from reportlab.pdfgen import canvas
from PIL import Image as PILImage

R=Path(__file__).resolve().parents[1];F=R/'figures';RES=R/'results'; OUT=R/'paceval_Decision_Tree_Mathematical_Execution_Whitepaper_EN.pdf'
for n,f in [('Lato','Lato-Regular.ttf'),('Lato-Bold','Lato-Bold.ttf'),('Lato-Italic','Lato-Italic.ttf')]:
 pdfmetrics.registerFont(TTFont(n,'/usr/share/fonts/truetype/lato/'+f))
W,H=A4;LEFT=48;RIGHT=48;BLUE=colors.HexColor('#203D63');DARK=colors.HexColor('#182332');PURPLE=colors.HexColor('#6B5291');LIME=colors.HexColor('#83A728');MUTED=colors.HexColor('#586A79')
ST={
 'title':ParagraphStyle('title',fontName='Lato-Bold',fontSize=26.8,leading=31.3,textColor=DARK,spaceAfter=12),
 'subtitle':ParagraphStyle('subtitle',fontName='Lato',fontSize=13.4,leading=18.6,textColor=BLUE,spaceAfter=13),
 'h1':ParagraphStyle('h1',fontName='Lato-Bold',fontSize=16.0,leading=20,textColor=BLUE,spaceAfter=11,keepWithNext=True),
 'h2':ParagraphStyle('h2',fontName='Lato-Bold',fontSize=11.5,leading=15.2,textColor=PURPLE,spaceBefore=11,spaceAfter=6,keepWithNext=True),
 'body':ParagraphStyle('body',fontName='Lato',fontSize=9.8,leading=14.9,textColor=DARK,spaceAfter=10),
 'small':ParagraphStyle('small',fontName='Lato',fontSize=8.7,leading=12.5,textColor=DARK,spaceAfter=6),
 'caption':ParagraphStyle('caption',fontName='Lato-Italic',fontSize=8.4,leading=11.7,textColor=MUTED,spaceBefore=5,spaceAfter=11),
 'micro':ParagraphStyle('micro',fontName='Lato-Bold',fontSize=9.2,leading=13,textColor=PURPLE,spaceAfter=11),
 'ref':ParagraphStyle('ref',fontName='Lato',fontSize=8.5,leading=12.5,textColor=DARK,spaceAfter=7),
}
class Doc(BaseDocTemplate): pass
D=Doc(str(OUT),pagesize=A4,leftMargin=LEFT,rightMargin=RIGHT,topMargin=63,bottomMargin=50,title='Decision Trees as Reusable Mathematical Execution Graphs',author='paceval scientific research',subject='Actual paceval execution of a complete structured twenty-level decision tree')
frame=Frame(LEFT,49,W-LEFT-RIGHT,H-112,leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)
def draw(c,d):
 c.saveState()
 if d.page>1:
  c.setFont('Lato-Bold',10);c.setFillColor(BLUE);c.drawString(LEFT,H-35,'paceval.')
  c.setFont('Lato',8);c.setFillColor(MUTED);c.drawRightString(W-RIGHT,H-35,'Decision Trees as Mathematical Execution Graphs')
  c.setLineWidth(.5);c.setStrokeColor(colors.HexColor('#D6DBE1'));c.line(LEFT,H-43,W-RIGHT,H-43)
 c.setStrokeColor(colors.HexColor('#D6DBE1'));c.line(LEFT,42,W-RIGHT,42)
 c.setFont('Lato',7.7);c.setFillColor(MUTED);c.drawString(LEFT,28,'Scientific functionality study  |  13 November 2026')
 c.drawRightString(W-RIGHT,28,str(d.page));c.restoreState()
D.addPageTemplates(PageTemplate(id='default',frames=frame,onPage=draw))
def P(x,k='body'):return Paragraph(x,ST[k])
def H1(number,text):return P(number+'  '+text,'h1')
def H2(text):return P(text,'h2')
def Pic(name,maxh=310,maxw=498):
 path=F/name
 with PILImage.open(path) as im:w,h=im.size
 f=min(maxh/h,maxw/w)
 return Image(str(path),width=w*f,height=h*f)
def Fig(name,desc,maxh=290):return [Pic(name,maxh=maxh),P(desc,'caption')]
def TableX(data,widths=None):
 t=Table([[P(str(s),'small') for s in row] for row in data],colWidths=widths if widths else [(W-LEFT-RIGHT)/len(data[0])]*len(data[0]),repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#EDF1F5')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F9FB')]),('LINEBELOW',(0,0),(-1,0),.8,BLUE),('LINEBELOW',(0,1),(-1,-1),.3,colors.HexColor('#DDE4E9')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]))
 return t

def eq(name,content,size=16,width=10.5):
 fig=plt.figure(figsize=(width,0.86),facecolor='white');ax=fig.add_axes([0,0,1,1]);ax.axis('off')
 ax.text(.025,.48,'$'+content+'$',fontsize=size,color='#243F60',va='center',ha='left')
 path=F/name;fig.savefig(path,dpi=220,facecolor='white');plt.close(fig)
 return Pic(name,maxh=65,maxw=498)

s=[]
s += [Spacer(1,14),P('paceval. | EXECUTED SCIENTIFIC RESEARCH','micro'),P('Decision Trees as Reusable<br/>Mathematical Execution Graphs','title'),P('From industrial quality rules to one million verified terminal decision paths','subtitle'),Pic('00_decision_tree_hero.png',maxh=258),Spacer(1,14),P('<b>13 November 2026</b>  |  English scientific research study  |  original paceval SDK 4.25','small'),HRFlowable(width='100%',thickness=1,color=LIME,spaceBefore=8,spaceAfter=14),P('<b>Executed research result.</b> The original paceval library evaluated 35 graphs in a six-level industrial quality-rule study. A further four persistent graphs executed every one of the <b>1,048,576 paths</b> of a separate complete 20-level structured binary decision tree, producing <b>4,194,304 graph outputs</b> with independently verified path and score values.'),P('The 20-level result concerns a structured tree admitting a compact mathematical expression; no fully expanded million-term formula or arbitrary independent leaf table was executed. The title image is a conceptual illustration, not a computed result.','caption'),PageBreak()]

s += [H1('01','Industrial use case and current state of the art'),P('Industrial inspection and condition monitoring systems evaluate measurements of temperature, vibration, load, pressure, current and drift. A production-quality workflow may first correct these measurements, calculate an interpretable rule score and then select an advisory outcome such as ACCEPT, REVIEW or REJECT. A rule is meaningful only if its input domain, thresholds, measurement context and model revision are specified.'),P('Tree-based classifiers and explicit rule systems are already established. Scikit-learn documents decision-tree learning and rule export, while newer research examines compiled tree inference and compact rule ensembles [1-4]. The specific research opportunity for paceval is <b>not</b> to train a classifier, but to represent the resulting mathematical conditions and associated scores as reusable computation objects.'),*Fig('01_executed_architecture.png','Figure 1. The implemented pipeline. paceval evaluates sensor-correction functions, mathematical tree expressions, quality scores and signed guard margins; C++ maintains input and decision state.',maxh=225),P('The demonstrator is a synthetic, read-only quality-scoring study. It does not claim industrial classification accuracy, metrological traceability, certified machinery release, or safety-controller functionality.'),PageBreak()]

s += [H1('02','The supplied four-leaf decision tree'),P('The motivating example has a root split on a, followed by different b thresholds on the two branches. Each terminal path is assigned a scalar value. A domain engineer can express the same tree as four mutually exclusive Boolean path indicators weighted by leaf values.'),eq('math_original_tree.png',r'f(a,b)=8I_{a<0,b<30}+11I_{a<0,b\geq30}+7I_{a\geq0,b<10}+9I_{a\geq0,b\geq10}',size=14.0),P('A real paceval computation evaluates this four-leaf rule, with host-side input-domain checks. Twelve scalar cases include split-boundary inputs. Every such case passed the independently implemented reference check.'),H2('Two mathematically equivalent tree encodings'),P('The expanded six-level pilot evaluates both (1) the sum of mutually exclusive path indicators, and (2) a nested binary expression. Both are registered as distinct paceval graphs and compared on actual synthetic sensor vectors. Boolean masking is not a promise of short-circuit or protected evaluation for undefined inactive branches.'),*Fig('11_formula_representation.png','Figure 2. Actual registered expression lengths for selected mathematical graph representations. Expression size is a structural property and is not interpreted as a hardware result.',maxh=235),PageBreak()]

s += [H1('03','Expanded synthetic industrial rule models'),P('The initial six-level models use corrected sensor features temperature, vibration, pressure, load, motor current and drift. They represent two independently available, fully specified mathematical versions, each with 64 leaves. The second version changes actual thresholds and leaf values while retaining the first version.'),eq('math_corrections.png',r'v_c=v_{raw}(1+0.002(T-25)),\quad p_c=p_{raw}-0.006(T-25)',size=16),P('After the tree assigns a base score, additional paceval graphs calculate a composite dimensionless quality score and signed margins to the specified acceptance and rejection boundaries. The C++ host then applies an illustrative discrete advisory status policy.'),*Fig('03_two_model_score_maps.png','Figure 3. Both model versions actually executed in paceval over the same controlled sensor grid. The maps illustrate model revision, not improved industrial prediction quality.',maxh=265),PageBreak()]

s += [H1('04','Mathematical score maps and control regions'),P('For each version, the model chain computes a path indicator, leaf index, base cost, continuous score correction, signed acceptance and rejection margins and six separate sensor guard margins. Real computation handles are reused across the data set. These functions are auditable independently of the host decision state.'),*Fig('02_model_v1_score_surface_3d.png','Figure 4. Dimensionless model-v1 quality-score surface from the executed paceval graph chain.',maxh=330),P('Within a fixed terminal leaf, the continuous correction admits explicit analytical partial derivatives. Across split thresholds, tree outputs are generally discontinuous and derivatives are not globally defined; sensitivity claims are therefore restricted to within-leaf regions.'),PageBreak()]

s += [H1('05','Controlled model changes and actionable outputs'),P('The scenario set consists of 1,692 unique synthetic sensor-input vectors, each processed under two model versions. Their decision labels are derived from paceval score and guard outputs using the documented host policy. All three result categories appear in the executed data. Neither model is claimed superior because both are synthetic.'),*Fig('05_quality_decision_regions.png','Figure 5. Synthetic accept, review and reject regions computed from the actual paceval outputs and explicit C++ decision policy.',maxh=290),*Fig('07_decision_outcome_counts.png','Figure 6. Number of advisory decisions in each model version, based solely on recorded experimental outputs.',maxh=160),PageBreak()]

s += [H1('06','Verified original six-level execution'),TableX([['Execution evidence','Verified scope'],['Persistent paceval graphs','35'],['Independent sensor vectors','1,692'],['Model-version decisions','3,384'],['Actual graph outputs','57,540'],['Multi-graph batch calls','6'],['Independent high-precision scalar checks','60,912'],['Independently verified complete decisions','3,384']],widths=[280,220]),Spacer(1,16),P('A separate native C++ traversal and an 80-decimal-digit Python reference were used for validation only. The published output values were produced by the original paceval shared library, not by these reference implementations. Complete formulas and function ownership are documented in `results/graph_registry.csv` and `results/math_execution_inventory.csv`.'),*Fig('08_analytic_sensitivities.png','Figure 7. Selected, actually executed within-leaf mathematical sensitivity functions.',maxh=225),PageBreak()]

s += [H1('07','Complete structured tree with 20 binary levels'),P('The additional research test constructs <b>twenty independent binary predicates</b>. Each path is represented by a 20-bit integer, with all possible combinations present. The study does not enumerate all leaves in the expression source. Instead, its leaf-identification function computes the binary index directly from the predicates.'),eq('math_index20.png',r'j(x)=\sum_{k=0}^{19}2^{19-k}I[x_k\geq0.5],\quad j\in\{0,\ldots,2^{20}-1\}',size=17),P('Two independently versioned leaf-score formulas use the path index, population count and a smooth analytical correction. They are declared and executed as actual paceval graphs. This construction exposes the full combinatorial decision space while retaining a compact and deterministic formula definition.'),*Fig('12_depth20_verified_coverage.png','Figure 8. Exhaustively verified path cardinalities grouped by number of true predicates. Each bar is derived from the observed paceval execution checks; the distribution totals 1,048,576.',maxh=270),PageBreak()]

s += [H1('08','One million paths: executed results'),TableX([['Evidence','Observed result'],['Binary decision levels','20'],['Terminal paths visited and independently verified','1,048,576'],['Persistent paceval functions','4'],['Actual graph outputs','4,194,304'],['Multi-graph batch calls','256'],['Exactly verified leaf indices','1,048,576'],['Native independent score checks','2,097,152'],['Separate 80-digit score checks','30 values at 15 selected leaves']],widths=[320,180]),Spacer(1,14),*Fig('13_depth20_versioned_scores.png','Figure 9. Recorded score samples across the entire indexed tree domain. Two simultaneously defined mathematical score versions are both evaluated through paceval.',maxh=235),P('The complete path run validates mathematical functionality for this <b>structured</b> tree. It does <b>not</b> show that an arbitrary million-leaf table of independently assigned values can be compressed to the same short formula, nor that an explicitly expanded million-term expression has been compiled.'),PageBreak()]

s += [H1('09','Execution ownership and traceable graph lifecycle'),TableX([['Mathematical component','Execution owner'],['Original four-leaf tree and six-level masked trees','paceval persistent graphs'],['Nested tree encodings, leaf identity, coverage','paceval persistent graphs'],['Sensor compensations and final risk-score corrections','paceval persistent graphs'],['Signed quality and sensor-guard margins','paceval persistent graphs'],['Within-leaf analytical sensitivities','paceval persistent graphs'],['Twenty-level path index and population count','paceval persistent graphs'],['Twenty-level versioned structured score functions','paceval persistent graphs'],['Data selection, test orchestration and result files','C++ host'],['Independent numeric and high-precision checks','C++ / Python reference only']],widths=[325,175]),Spacer(1,12),P('The executed mathematical registration is recorded separately for the first 35 graphs and the four additional depth-20 graphs. The latter use the documented multi-graph API for all 1,048,576 binary-path inputs.'),P('All graph-handle creation and deletion is performed using the original SDK 4.25 interfaces. The original Linux shared library is provided externally and is intentionally not part of the public ZIP.'),PageBreak()]

s += [H1('10','Research limitations and reproducibility'),P('The project validates software mathematical execution, not the accuracy of physical sensors or the predictive value of a trained classifier. There is no site deployment, authenticated model approval, real production decision system, interval proof or hardware implementation. The original six-level and additional 20-level trees are independent controlled synthetic experiments.'),P('The exhaustive 20-level test deliberately covers all unambiguous binary path combinations. The narrowly scoped conclusion does not imply compact source representation for arbitrary independently assigned million-leaf values. Quality decisions require an externally justified tolerance, data-quality policy and applicable domain validation.'),H2('Reproducing the project'),P('From the extracted repository folder, use `cmake -S src -B build -DCMAKE_BUILD_TYPE=Release -DPACEVAL_RUNTIME=/absolute/path/to/libpaceval_linux_sharedLIB.so`, then `cmake --build build -j` and `ctest --test-dir build --output-on-failure`. Both executable targets, `decision_tree` and `depth20_exhaustive`, are built and tested. Python scripts under `src/` regenerate the diagrams, reference audits and this PDF.'),P('The independent 80-digit audit is under `results/depth20_80digit_audit.json`; exact formulas are stored under `results/depth20_graph_registry.csv`, and the complete exhaustive execution summary is under `results/depth20_exhaustive_audit.txt`.'),H2('Scientific interpretation'),P('The executed results demonstrate a viable mathematical representation for explicitly defined decision rules, the simultaneous preservation of formula versions, genuine graph reuse and exhaustive evaluation of a large <i>structured</i> decision space in the original paceval runtime. No CPU, GPU, FPGA or ASIC performance comparisons form part of this functionality report.'),PageBreak()]

s += [H1('11','References and source provenance'),P('[1] Scikit-learn. Decision Trees: official user guide. https://scikit-learn.org/stable/modules/tree.html','ref'),P('[2] Scikit-learn. export_text: human-readable decision tree rules. https://scikit-learn.org/stable/modules/generated/sklearn.tree.export_text.html','ref'),P('[3] Behzadimanesh et al. (2026). Sparse oblique rule boosting for simpler additive rule ensembles. Data Mining and Knowledge Discovery. DOI: 10.1007/s10618-026-01241-8.','ref'),P('[4] Su et al. (2024). TreeHouse: An MLIR-based Compilation Flow for Real-Time Tree-based Inference. ACM Transactions on Embedded Computing Systems. DOI: 10.1145/3704727.','ref'),P('[5] ISA/IEC 62443. Industrial Automation and Control Systems Cybersecurity. https://www.isa.org/standards-and-publications/isa-standards/isa-iec-62443-series-of-standards','ref'),P('[6] paceval. Public C/C++ Mathematical Engine API, original SDK 4.25. https://paceval.com/api/','ref'),P('[7] Original research diagram provided by the project initiator: four-leaf tree with conditional expression equivalents (2026).','ref'),Spacer(1,15),P('<b>Reproducibility statement.</b> The source formulas, complete C++ implementation, archived recorded outputs, independent validation programs, graphical sources and this report-generation script are distributed together. The external paceval runtime and licensed external sensor data are not redistributed. Every industrial setting and threshold in the first study is synthetic.','small'),P('Conceptual title illustration. Real quantitative diagrams originate from the archived paceval C++ execution output files.','caption')]
D.build(s)
print('PDF',OUT,'bytes',OUT.stat().st_size)
